SELECT s.openid, u.nickname, u.headimgurl, u.remark, s.last_msg_time AS lastMsgTime, s.last_msg_summary AS lastMsgSummary, s.last_in_time AS lastInTime, AS unreadCount FROM wx_msg_session s LEFT JOIN wx_user u ON u.appid = s.appid AND u.openid = s.openid LEFT JOIN wx_msg_read r ON r.appid = s.appid AND r.openid = s.openid AND r.user_id = #{userId} WHERE s.appid = #{appid} AND s.has_real_msg = 1
AND (u.nickname LIKE CONCAT('%', #{keyword}, '%') OR u.remark LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY s.last_msg_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM wx_msg_session s
LEFT JOIN wx_msg_read r ON r.appid = s.appid AND r.openid = s.openid AND r.user_id = #{userId}
WHERE s.appid = #{appid}
  AND s.has_real_msg = 1
  AND  > 0
